69:       }
70:     }
71:     const reference = sourceRangeSchema.parse({ type: 'sourceRange', sourceId: input.sourceId, path: input.path,
72:       startLine: input.startLine, endLine: input.endLine ?? file.startLine + file.lines.length - 1, version });
