77:   private async load(reference: AgentContextSourceRange) {
78:     sourceRangeSchema.parse(reference);
79:     const file = reference.version.kind === 'snapshot'
80:       ? sourceFileSchema.parse(await this.blobs.get(reference.version.contentHash))
81:       : await this.pinnedFile(await this.source(reference.sourceId), reference.version.commit, reference.path);
82:     sourceRangeText(reference, file);
83:     return file;
84:   }
85:   async read(reference: AgentContextSourceRange) { return sourceRangeText(reference, await this.load(reference)); }
86:   async persist(raw: AgentContextSnapshot) {
87:     const context = AgentContext.fromSnapshot(raw), snapshot = context.toSnapshot();
88:     for (const file of Object.values(snapshot.sourceFiles ?? {})) await this.blobs.put(file);
89:     // Check references before publication, including imported descriptors with missing blobs.
90:     const seen = new Set<string>();
91:     for (const block of agentContextSourceRanges(snapshot.messages)) {
92:       const key = JSON.stringify(block);
93:       if (!seen.has(key)) { await this.load(block); seen.add(key); }
94:     }
95:     return context.withoutSourceFiles();
96:   }
97:   async portable(raw: AgentContextSnapshot) {
98:     const context = AgentContext.fromSnapshot(raw), snapshot = context.toSnapshot();
99:     const files: Record<string, AgentContextSourceFile> = {};
100:     const references = new Map<string, AgentContextSourceRange>();
101:     for (const block of agentContextSourceRanges(snapshot.messages)) {
102:       const key = JSON.stringify(block);
103:       if (references.has(key)) continue;
104:       const file = block.version.kind === 'snapshot' && snapshot.sourceFiles?.[block.version.contentHash]
105:         || await this.load(block);
106:       // Portable context contains only its selected evidence, not unrelated file lines.
107:       const selected = { startLine: block.startLine,
108:         lines: file.lines.slice(block.startLine - file.startLine, block.endLine - file.startLine + 1) };
109:       const contentHash = sourceFileHash(selected); files[contentHash] = selected;
110:       references.set(key, { ...block, version: { kind: 'snapshot', contentHash } });
111:     }
112:     const replace = (block: { type: string }) => block.type === 'sourceRange' ? references.get(JSON.stringify(block))! : block;
113:     const messages = snapshot.messages.map(message => ({ ...message, content: message.content.map(block => block.type === 'section'
114:       ? { ...block, content: block.content.map(replace) } : replace(block)) }));
115:     return context.withMessages(messages, files).toSnapshot();
116:   }
117: }
